func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestMax(t *testing.T) {
	cases := []struct {
		a, b, want int
	}{
		{2, 3, 3},
		{3, 2, 3},
		{5, 5, 5},
		{-1, -2, -1},
	}
	for _, tc := range cases {
		if got := max(tc.a, tc.b); got != tc.want {
			t.Fatalf("max(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.want)
		}
	}
}

